from typing import List

class Solution:
    def letterCombinations(self, digits: str) -> List[str]:
        if not digits:
            return []
        phone = {"2": "abc", "3": "def", "4": "ghi", "5": "jkl",
                 "6": "mno", "7": "pqrs", "8": "tuv", "9": "wxyz"}
        result = []
        chars = [""] * len(digits)

        def dfs(i: int) -> None:
            if i == len(digits):
                result.append("".join(chars))
                return
            for ch in phone[digits[i]]:
                chars[i] = ch
                dfs(i + 1)

        dfs(0)
        return result

